insert into public.task_templates(id,title,category,horizon,priority,content) values('review-entry-documents','Review your entry documents and I-20 start date','campus','first_48_hours','high','{"id": "review-entry-documents", "title": "Review your entry documents and I-20 start date", "category": "campus", "horizon": "first_48_hours", "priority": "high", "rule": "always", "why": "Review the official instructions that apply to your student category; mark not applicable when appropriate.", "steps": ["If you are making initial F-1 entry, review the program start date printed on your I-20; the entry window is based on that date, not the first class day.", "Use the official DHS and ISSO instructions to prepare; carry your passport, visa and I-20 in your carry-on.", "Do not upload immigration documents to CampusBridge. Mark this task not applicable if it does not apply to you."], "help": "ISSO", "resourceId": "spring-entry"}') on conflict(id) do update set title=excluded.title,category=excluded.category,horizon=excluded.horizon,priority=excluded.priority,content=excluded.content;
