insert into public.task_templates(id,title,category,horizon,priority,content) values('complete-international-orientation','Check your Spring 2027 orientation requirements','campus','first_48_hours','high','{"id": "complete-international-orientation", "title": "Check your Spring 2027 orientation requirements", "category": "campus", "horizon": "first_48_hours", "priority": "high", "rule": "always", "why": "Review the official instructions that apply to your student category; mark not applicable when appropriate.", "steps": ["New F/J graduate and exchange students must follow International Student Orientation requirements; undergraduates use their own orientation instructions.", "Registration and pre-arrival modules open October 28. Complete the modules one day before the January 13 session. Confirm opening times on the official page.", "January 13 check-in is 12:30–1:30 p.m., with orientation 2–7 p.m. at ATC Lecture Hall; confirm your assigned session and the $50 attendance fee."], "help": "UT Dallas Intercultural Programs", "resourceId": "spring-orientation"}') on conflict(id) do update set title=excluded.title,category=excluded.category,horizon=excluded.horizon,priority=excluded.priority,content=excluded.content;
