insert into public.task_templates(id,title,category,horizon,priority,content) values('review-health-requirements','Review screening, vaccination and registration holds','campus','first_48_hours','high','{"id": "review-health-requirements", "title": "Review screening, vaccination and registration holds", "category": "campus", "horizon": "first_48_hours", "priority": "high", "rule": "always", "why": "Review the official instructions that apply to your student category; mark not applicable when appropriate.", "steps": ["People born outside the United States should review the required U.S. IGRA/T-Spot screening instructions with Student Health Center. December 1 is the appointment-link opening, not a completion deadline.", "Entering students under 22 should check the Registrar’s meningitis documentation and exemption instructions; Spring 2027 vaccine administration cutoff is January 9 if required.", "Use official university channels for medical records. CampusBridge does not collect birth dates, health records or make eligibility decisions."], "help": "UT Dallas Student Health Center and Registrar", "resourceId": "spring-health"}') on conflict(id) do update set title=excluded.title,category=excluded.category,horizon=excluded.horizon,priority=excluded.priority,content=excluded.content;
