insert into public.task_templates(id,title,category,horizon,priority,content) values('review-international-insurance','Review your international student insurance coverage','campus','first_48_hours','high','{"id": "review-international-insurance", "title": "Review your international student insurance coverage", "category": "campus", "horizon": "first_48_hours", "priority": "high", "rule": "always", "why": "Review the official instructions that apply to your student category; mark not applicable when appropriate.", "steps": ["F-1/F-2/J-1/J-2 students should review automatic UT SHIP enrollment and coverage requirements.", "A waiver requires eligible comparable alternative coverage and university approval. Check the official waiver window; submitting a request does not cancel required coverage.", "Spring medical coverage is January 1–May 31. Read current rates, dependent costs and university instructions before budgeting."], "help": "UT Dallas Student Health Insurance", "resourceId": "spring-insurance"}') on conflict(id) do update set title=excluded.title,category=excluded.category,horizon=excluded.horizon,priority=excluded.priority,content=excluded.content;
